package main

import (
	"sort"
	"strings"
)

func TopKWords(text string, k int) []string {
	// Extract words: maximal runs of ASCII letters
	var words []string
	current := ""
	for _, ch := range text {
		if (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') {
			current += string(ch)
		} else {
			if current != "" {
				words = append(words, current)
				current = ""
			}
		}
	}
	if current != "" {
		words = append(words, current)
	}

	// Convert all words to lowercase
	for i := range words {
		words[i] = strings.ToLower(words[i])
	}

	// Count frequencies
	freq := make(map[string]int)
	for _, w := range words {
		freq[w]++
	}

	// Get unique words
	unique := make([]string, 0, len(freq))
	for w := range freq {
		unique = append(unique, w)
	}

	// Sort by frequency descending, then alphabetically ascending for ties
	sort.Slice(unique, func(i, j int) bool {
		if freq[unique[i]] != freq[unique[j]] {
			return freq[unique[i]] > freq[unique[j]]
		}
		return unique[i] < unique[j]
	})

	// Determine how many to return
	n := k
	if n > len(unique) {
		n = len(unique)
	}
	if n < 0 {
		n = 0
	}
	return unique[:n]
}
