fn compress(s: &str) -> String {
    let mut it = s.chars();
    let mut result = String::new();
    while let Some(c) = it.next() {
        let mut count = 1;
        while it.next() == Some(c) {
            count += 1;
        }
        if count > 1 {
            result.push(c);
            result.push_str(&count.to_string());
        } else {
            result.push(c);
        }
    }
    result
}
