fn eval_rpn(tokens: &[&str]) -> Option<i64> {
    let mut stack: Vec<i64> = Vec::new();

    for token in tokens {
        match token {
            "+" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a + b);
            }
            "-" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a - b);
            }
            "*" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                stack.push(a * b);
            }
            "/" => {
                let b = stack.pop()?;
                if b == 0 {
                    return None;
                }
                let a = stack.pop()?;
                stack.push(a / b);
            }
            _ => {
                match token.parse::<i64>() {
                    Ok(n) => stack.push(n),
                    Err(_) => return None,
                }
            }
        }
    }

    if stack.len() == 1 {
        stack.pop()
    } else {
        None
    }
}
